import {initializeApp} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-app.js';
import {getAuth,setPersistence,browserSessionPersistence,onAuthStateChanged,signInWithEmailAndPassword,signOut} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-auth.js';
import {getFirestore,doc,collection,getDocFromServer,getDocsFromServer,query,where,onSnapshot,setDoc,addDoc,updateDoc,writeBatch,serverTimestamp} from 'https://www.gstatic.com/firebasejs/13.1.0/firebase-firestore.js';
const $=s=>document.querySelector(s),W=SpatiaWorkspace,G=GeoEngine,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=initializeApp(SPATIA_FIREBASE_CONFIG,'build-intelligence'),auth=getAuth(app),db=getFirestore(app);let user=null,building='',membership=null,stops=[],tasks=[],inspections=[],publics=[],elements=[],busy=false;
let model;try{model=G.validate(JSON.parse(localStorage.getItem(W.MODEL_KEY)))}catch{model=G.seed()}$('#sharedBuilding').value=W.buildingId(model);
const role=()=>membership?.role,staff=()=>role()==='manager'||role()==='systemAdmin',path=(kind,id)=>id?doc(db,'buildings',building,kind,id):collection(db,'buildings',building,kind);
function message(t,bad=false){$('#sharedStatus').textContent=t;$('#sharedStatus').className='status '+(bad?'error':'good')}
function clear(){const dialog=document.querySelector('#sharedInspectionDialog');if(dialog){dialog.close();dialog.replaceChildren()}stops.forEach(fn=>fn());stops=[];tasks=[];inspections=[];publics=[];elements=[];membership=null;$('#sharedWorkspace').hidden=true;$('#membership').textContent='건물을 열면 서버에서 멤버십을 확인합니다.';for(const id of ['sharedRequests','inspectionList','publicUpdates'])$('#'+id).replaceChildren()}
function error(e){if(e.code==='permission-denied')clear();message(e.code==='permission-denied'?'서버가 접근을 거부했습니다. 건물 멤버십과 Firestore 규칙 배포 상태를 확인하세요.':e.code==='failed-precondition'?'Firestore 데이터베이스·인덱스 설정을 확인하세요.':e.code==='auth/invalid-credential'?'이메일 또는 비밀번호를 확인하세요.':e.code==='unavailable'?'서버 연결이 끊겼습니다. 이 화면에서는 오프라인 저장을 지원하지 않습니다.':e.code?.startsWith('auth/')?'로그인 설정·도메인·계정 상태를 확인하세요.':e.message||'요청 처리 중 오류가 발생했습니다.',true)}
async function action(fn){if(busy)return;busy=true;document.querySelectorAll('#sharedWorkspace button').forEach(b=>b.disabled=true);try{await fn()}catch(e){error(e)}finally{busy=false;document.querySelectorAll('#sharedWorkspace button').forEach(b=>b.disabled=false)}}
await setPersistence(auth,browserSessionPersistence);$('#sharedLogin').disabled=false;onAuthStateChanged(auth,u=>{clear();user=u;$('#sharedAccount').textContent=u?'로그인 UID: '+u.uid+' · '+u.email:'로그인 전';$('#sharedPassword').value='';$('#sharedLogin').disabled=!!u;$('#sharedLogout').disabled=!u;$('#openBuilding').disabled=!u;message(u?'로그인 완료 · 건물 ID를 확인하고 내 권한을 조회하세요.':'계정으로 로그인하세요.');});
$('#sharedAuth').onsubmit=e=>{e.preventDefault();action(async()=>{await signInWithEmailAndPassword(auth,$('#sharedEmail').value.trim(),$('#sharedPassword').value);$('#sharedPassword').value=''})};$('#sharedLogout').onclick=()=>action(()=>signOut(auth));
function watch(kind,q,update){stops.push(onSnapshot(q,{includeMetadataChanges:true},snapshot=>{if(snapshot.metadata.fromCache){message('서버 확인을 기다리는 중입니다. 캐시 데이터를 업무 기록으로 표시하지 않습니다.');return}update(snapshot.docs.map(d=>({id:d.id,...d.data()})));render()},error))}
$('#buildingConnect').onsubmit=e=>{e.preventDefault();action(async()=>{clear();if(!user)throw Error('먼저 로그인하세요.');building=$('#sharedBuilding').value.trim();if(!/^[A-Za-z0-9_-]{1,100}$/.test(building))throw Error('건물 ID 형식을 확인하세요.');const own=await getDocFromServer(path('members',user.uid)),admin=await getDocFromServer(doc(db,'systemAdmins',user.uid));if(admin.exists()&&admin.data().enabled===true)membership={role:'systemAdmin',units:[]};else if(own.exists()&&['resident','manager','expert'].includes(own.data().role)&&Array.isArray(own.data().units)&&own.data().units.length<=20)membership=own.data();else throw Error('이 건물에 등록된 권한이 없습니다. 시스템 관리자에게 UID와 건물 ID를 전달하세요.');$('#membership').textContent='서버 권한: '+role()+' · 세대: '+(membership.units.join(', ')||'담당 건물');$('#workspaceIdentity').textContent='건물 '+building+' · UID '+user.uid+' · '+role();$('#sharedWorkspace').hidden=false;$('#modelRegistration').hidden=!staff();$('#membershipAdmin').hidden=role()!=='systemAdmin';$('#sharedNewRequest').hidden=!(role()==='resident'||staff());$('#privateInspections').hidden=!(staff()||role()==='expert');const eq=staff()||role()==='expert'?path('elements'):query(path('elements'),where('unitId','in',[...new Set([...membership.units,'common'])]));const rows=await getDocsFromServer(eq);elements=rows.docs.map(d=>({id:d.id,...d.data()}));$('#sharedElement').replaceChildren();for(const el of elements){const option=document.createElement('option');option.value=el.id;option.textContent=el.name+' · '+el.id+' · '+el.unitId;$('#sharedElement').append(option)}watch('requests',staff()?path('requests'):query(path('requests'),where(role()==='expert'?'assignedUid':'ownerUid','==',user.uid)),v=>tasks=v);if(staff()||role()==='expert')watch('inspections',staff()?path('inspections'):query(path('inspections'),where('authorUid','==',user.uid)),v=>inspections=v);watch('publicUpdates',staff()||role()==='expert'?path('publicUpdates'):query(path('publicUpdates'),where('unitId','in',[...new Set([...membership.units,'common'])])),v=>publics=v);message('서버 권한 확인 완료 · 공유 기록을 읽는 중입니다.');})};
$('#registerElements').onclick=()=>action(async()=>{if(W.buildingId(model)!==building)throw Error('현재 로컬 모델의 건물 ID와 연결된 건물 ID가 다릅니다.');if(!confirm('현재 모델의 '+model.elements.length+'개 구조물·자재를 이 건물에 등록·갱신할까요?'))return;await setDoc(doc(db,'buildings',building),{buildingId:building,name:model.name,updatedAt:serverTimestamp()});for(let start=0;start<model.elements.length;start+=200){const batch=writeBatch(db);for(const e of model.elements.slice(start,start+200))batch.set(path('elements',e.id),{buildingId:building,unitId:e.unit,floorId:building+'-F'+e.floor,name:e.name,type:e.type,material:e.material,min:e.min,max:e.max,ifcGuid:e.ifcGuid||''});await batch.commit()}message('서버에서 구조물 등록을 확인했습니다. 건물을 다시 열어 목록을 갱신하세요.');});
$('#sharedRequestForm').onsubmit=e=>{e.preventDefault();action(async()=>{const element=elements.find(x=>x.id===$('#sharedElement').value);if(!element)throw Error('관리자가 등록한 구조물을 선택하세요.');const description=$('#sharedDescription').value.trim(),title=$('#sharedTitle').value.trim();if(description.length<5||!title)throw Error('제목과 5자 이상의 설명을 입력하세요.');const r=await addDoc(path('requests'),{buildingId:building,unitId:element.unitId,elementId:element.id,ownerUid:user.uid,assignedUid:'',stage:0,title,description,dueDate:'',createdAt:serverTimestamp(),updatedAt:serverTimestamp()});$('#sharedRequestForm').reset();message('서버 요청 등록 완료 · '+r.id);})};
const stages=['접수 완료','담당자 배정','현장 점검','보수 예정','보수 완료','입주자 확인'];
function render(){const container=$('#sharedRequests');container.innerHTML=tasks.map(t=>`<article><h3>${esc(t.title)}</h3><small>${esc(t.id)} · ${esc(t.unitId)} · ${esc(t.elementId)}</small><p>${esc(t.description)}</p><b>${stages[t.stage]||'상태 확인 필요'}</b><p>다음 일정: ${esc(t.dueDate||'미정')} · 담당 UID: ${esc(t.assignedUid||'미배정')}</p>${staff()?`<form data-transition="${esc(t.id)}"><label>배정할 전문가 UID<input name="assignedUid" value="${esc(t.assignedUid)}" maxlength="128"></label><label>처리 상태<select name="stage">${stages.slice(0,5).map((s,i)=>`<option value="${i}" ${i===t.stage?'selected':''} ${i<t.stage?'disabled':''}>${s}</option>`).join('')}</select></label><label>다음 조치 예정일<input type="date" name="dueDate" value="${esc(t.dueDate)}"></label><button>처리 상태 서버 저장</button></form>`:''}${role()==='resident'&&t.ownerUid===user.uid&&t.stage===4?`<button data-confirm="${esc(t.id)}">보수 결과 확인 완료</button>`:''}${role()==='expert'&&t.assignedUid===user.uid?`<button data-inspect="${esc(t.id)}">비공개 점검 기록 작성</button>`:''}</article>`).join('')||'<p>이 계정으로 조회할 수 있는 요청이 없습니다.</p>';
$('#inspectionList').innerHTML=inspections.map(i=>`<article><h3>${esc(i.elementId)} · 개정 ${i.revision}</h3><p class="inspection-private">${esc(i.raw)}</p><p>쉬운 설명: ${esc(i.plain)}</p><p>다음 조치: ${esc(i.next)}</p><b>${i.reviewed?'전문가 검토 완료':'검토 전 · 공개 불가'}</b>${staff()&&i.reviewed?`<button data-publish="${esc(i.id)}">현재 검토본을 입주자에게 공개 승인</button>`:''}</article>`).join('')||'<p>접근 가능한 점검 원문이 없습니다.</p>';
$('#publicUpdates').innerHTML=publics.map(p=>`<article><h3>${esc(p.elementId)}</h3><p>${esc(p.plain)}</p><p>다음 조치: ${esc(p.next)}</p><small>승인된 개정 ${p.reviewedRevision} · ${esc(p.approvedAt?.toDate?.().toLocaleString('ko-KR')||'서버 시각 확인 중')}</small></article>`).join('')||'<p>이 계정에 공개된 설명이 없습니다.</p>';
for(const form of container.querySelectorAll('[data-transition]'))form.onsubmit=e=>{e.preventDefault();action(async()=>{const data=new FormData(form);await updateDoc(path('requests',form.dataset.transition),{stage:+data.get('stage'),assignedUid:String(data.get('assignedUid')).trim(),dueDate:String(data.get('dueDate')),updatedAt:serverTimestamp()});message('서버가 처리 상태 변경을 확인했습니다.');})};for(const b of container.querySelectorAll('[data-confirm]'))b.onclick=()=>action(async()=>{await updateDoc(path('requests',b.dataset.confirm),{stage:5,updatedAt:serverTimestamp()});message('입주자 확인을 서버에 저장했습니다.')});for(const b of container.querySelectorAll('[data-inspect]'))b.onclick=()=>inspectionForm(tasks.find(t=>t.id===b.dataset.inspect));for(const b of $('#inspectionList').querySelectorAll('[data-publish]'))b.onclick=()=>action(async()=>{const i=inspections.find(x=>x.id===b.dataset.publish);if(!confirm('검토된 쉬운 설명과 다음 조치를 해당 세대에 공개할까요? 원문은 포함되지 않습니다.'))return;await setDoc(path('publicUpdates',i.id),{requestId:i.requestId,inspectionId:i.id,buildingId:building,unitId:i.unitId,elementId:i.elementId,plain:i.plain,next:i.next,reviewedRevision:i.revision,approvedBy:user.uid,approvedAt:serverTimestamp()});message('서버가 공개 승인을 확인했습니다.');});}
function inspectionForm(task){let dialog=document.querySelector('#sharedInspectionDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='sharedInspectionDialog';document.body.append(dialog)}const previous=inspections.find(i=>i.requestId===task.id&&i.authorUid===user.uid);dialog.innerHTML=`<form id="inspectionForm" style="max-width:600px;padding:20px"><h2>담당 요청의 비공개 점검 기록</h2><p>${esc(task.elementId)} · 원문은 입주자에게 전송하지 않습니다.</p><label>전문가 원문<textarea name="raw" required maxlength="3000">${esc(previous?.raw||'')}</textarea></label><label>쉬운 설명<textarea name="plain" required maxlength="1500">${esc(previous?.plain||'')}</textarea></label><label>다음 조치·예정일<textarea name="next" maxlength="1000">${esc(previous?.next||'')}</textarea></label><label><input name="reviewed" type="checkbox">설명을 직접 검토했습니다.</label><p class="meta">AI 모델은 연결하지 않았습니다. 전문가가 작성·검토한 설명만 관리자가 공개할 수 있습니다.</p><div class="actions"><button class="primary">비공개 서버 저장</button><button type="button" id="cancelInspection">취소</button></div></form>`;dialog.showModal();dialog.querySelector('#cancelInspection').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();action(async()=>{const form=new FormData(e.target),data={requestId:task.id,buildingId:building,unitId:task.unitId,elementId:task.elementId,authorUid:user.uid,raw:String(form.get('raw')).trim(),plain:String(form.get('plain')).trim(),next:String(form.get('next')).trim(),reviewed:form.get('reviewed')==='on',revision:(previous?.revision||0)+1,updatedAt:serverTimestamp()};if(previous)await setDoc(path('inspections',previous.id),data);else await addDoc(path('inspections'),data);dialog.close();message('서버가 비공개 점검 기록 저장을 확인했습니다.');})}}

$('#membershipForm').onsubmit=e=>{e.preventDefault();action(async()=>{if(role()!=='systemAdmin')throw Error('시스템 관리자 권한이 필요합니다.');const uid=$('#memberUid').value.trim(),r=$('#memberRole').value,units=[...new Set($('#memberUnits').value.split(',').map(x=>x.trim()).filter(Boolean))];if(!uid||uid.includes('/')||units.length>20||units.some(x=>!/^[-A-Za-z0-9_]{1,100}$/.test(x)))throw Error('UID와 20개 이하의 세대 ID를 확인하세요.');if(!confirm('UID '+uid+' 계정에 이 건물의 '+r+' 권한을 등록·갱신할까요?'))return;await setDoc(path('members',uid),{role:r,units});message('서버에서 멤버십 갱신을 확인했습니다. 해당 계정으로 다시 건물을 열어 확인하세요.');})};
